use super::*;
use crate::pet_runtime::{planning_feedback::Feedback,planning_journal::Request,authority_store::Fault as AuthorityFault};
fn feedback(a:&Authority,g:&Record,o:&Owned,ready:&Ready)->Feedback {let row=&g.admissions[0];a.record_planning_feedback(&row.spec,row.proof.as_ref().unwrap(),o.lease(),ready.scope(),crate::assistant_memory::now()).unwrap()}
fn context(a:&Authority,g:&Record,o:&Owned,request:&str)->crate::pet_runtime::authority::Result<crate::pet_runtime::planning_context::Context> {
    let row=&g.admissions[0];let request=Request::capture(g,&row.spec,o.lease(),request).map_err(|_|Failure::Changed)?;a.planning_context(&row.spec,row.proof.as_ref().unwrap(),o.lease(),request,crate::assistant_memory::now())
}
fn propose(a:&Authority,g:&Record,o:&Owned,request:&str,volume:u8) {
    let text=json!({"kind":"plan","description":"Reconcile the native unmet volume criterion","steps":[{"description":"Set volume","postcondition":format!("{volume} percent"),"operation":{"operationId":"spotify.control","version":1,"arguments":{"action":"set_volume","volume":volume}}}],"criteria":[{"criterionIndex":0,"predicate":{"kind":"spotifyPlayback","status":"paused"}},{"criterionIndex":1,"predicate":{"kind":"spotifyVolume","percent":17}}]}).to_string();
    let row=&g.admissions[0];let proof=row.proof.as_ref().unwrap();let request_native=Request::capture(g,&row.spec,o.lease(),request).unwrap();let at=crate::assistant_memory::now();let attempt=Attempt {id:nonce().unwrap(),request_id:request.into(),input_hash:model::fingerprint(&(request,&text)).unwrap(),kind:Kind::Model,output_reserved:2048,phase:Phase::Reserved,accepted_output:None,reserved_at:at,started_at:None,finished_at:None};
    a.reserve_planning_attempt(&row.spec,proof,o.lease(),&attempt,&request_native,at).unwrap();a.start_attempt(&row.spec,proof,o.lease(),&attempt,at).unwrap();a.finish_attempt(&row.spec,proof,o.lease(),&attempt,Some(text.len() as u64),at).unwrap();let result=a.seal_result(&row.spec,proof,o.lease(),&attempt,&text,text.len() as u64,at).unwrap();crate::pet_runtime::results::publish(a,&row.spec,proof,&result).unwrap();reconcile(a,g,o,request,crate::assistant_memory::now()).unwrap();
}
fn last_review(o:&Owned,g:&Record,bus:&Bus,request:&str)->(Approved,Ready) {
    o.review_recipe_with_criteria(g,&g.plans.last().unwrap().id,request,Arc::new(Target::fixture_at(&bus.address).unwrap()),&config(),&[],crate::assistant_memory::now()).unwrap().approve(o,g,&config(),crate::assistant_memory::now()).unwrap()
}
#[test]fn only_immutable_native_final_feedback_unlocks_a_round_and_preserves_original_measurement() {
    let(f,a,g,_p,o,_)=setup_custom(true,18,4);let bus=Bus::new();let player=Player::new(&bus,"Private feedback player");let(approved,ready)=reviewed(&o,&g,&bus);register(&a,&g,&o,&approved,&ready);
    assert_eq!(o.run_recipe_for_store(&native(&f),&g,&ready,||Ok(config()),|_|{}).unwrap().outcome,Outcome::CriteriaUnmet);assert_eq!(context(&a,&g,&o,"round-2").err(),Some(Failure::RecoveryRequired));
    let first=feedback(&a,&g,&o,&ready);assert!(first.known);assert_eq!(first.met(),1);let c=context(&a,&g,&o,"round-2").unwrap();assert_eq!(c.input.remaining.model_calls,2);assert_eq!(c.input.remaining.tool_calls,2);assert_eq!(c.input.remaining.rounds,2);assert_eq!(c.input.remaining.best_verified_criteria,1);assert_eq!(c.input.remaining.consecutive_no_progress,0);assert_eq!(c.input.observations[0].snapshot.as_ref().unwrap().volume,0.18);
    player.state.lock().unwrap().volume=0.9;player.state.lock().unwrap().status="Playing".into();assert_eq!(feedback(&a,&g,&o,&ready),first);let c=context(&a,&g,&o,"round-2").unwrap();assert_eq!(c.input.observations[0].snapshot.as_ref().unwrap().volume,0.18);assert_eq!(player.calls.lock().unwrap().len(),2);
    assert_eq!(g.admissions[0].spec.budget.max_tool_calls,4);assert_eq!(c.input.remaining.deadline_at,g.admissions[0].spec.budget.deadline_at);
}
#[test]fn a_second_known_plan_reuses_original_budget_and_completes_the_same_goal() {
    let(f,a,g,_p,o,_)=setup_custom(true,18,4);let bus=Bus::new();let player=Player::new(&bus,"Private replanning player");let(approved,ready)=reviewed(&o,&g,&bus);register(&a,&g,&o,&approved,&ready);assert_eq!(o.run_recipe_for_store(&native(&f),&g,&ready,||Ok(config()),|_|{}).unwrap().outcome,Outcome::CriteriaUnmet);feedback(&a,&g,&o,&ready);
    propose(&a,&g,&o,"round-2",17);let g2=o.publish_generated_plan(&native(&f),"round-2",crate::assistant_memory::now()).unwrap().receipt.record;assert_eq!(g2.generated_plans.len(),2);assert!(!ready.scope().matches(&g2));let(approved2,ready2)=last_review(&o,&g2,&bus,"approve-round-2");register(&a,&g2,&o,&approved2,&ready2);
    assert_eq!(o.run_recipe_for_store(&native(&f),&g2,&ready2,||Ok(config()),|_|{}).unwrap().outcome,Outcome::GoalCompleted);let final_feedback=feedback(&a,&g2,&o,&ready2);assert!(final_feedback.known);assert_eq!(final_feedback.met(),2);assert!(context(&a,&g2,&o,"round-3").is_err());
    let final_goal=native(&f).read(&g.id,"ai_ollama").unwrap();assert_eq!(final_goal.state,State::Completed);assert_eq!(final_goal.spec,g.spec);assert_eq!(player.calls.lock().unwrap().len(),3);let ledger=grant(&f,&g)["body"]["budgetUsage"].clone();let calls=ledger["attempts"].as_array().unwrap();assert_eq!(calls.len(),5);assert_eq!(calls.iter().filter(|c|c["kind"]=="model").count(),2);assert_eq!(calls.iter().filter(|c|c["kind"]=="tool").count(),3);
}
#[test]fn valid_feedback_json_or_an_approved_recipe_without_native_verification_cannot_unlock_planning() {
    let(f,a,g,_p,o,_)=setup_custom(true,18,4);let bus=Bus::new();let _player=Player::new(&bus,"Private fake feedback");let(approved,ready)=reviewed(&o,&g,&bus);register(&a,&g,&o,&approved,&ready);let row=&g.admissions[0];let proof=row.proof.as_ref().unwrap();
    assert_eq!(a.record_planning_feedback(&row.spec,proof,o.lease(),ready.scope(),crate::assistant_memory::now()).err(),Some(Failure::RecoveryRequired));let at=crate::assistant_memory::now();let fake=Feedback {schema_version:1,recipe_id:ready.scope().id.clone(),plan_id:ready.scope().plan_id.clone(),report_hash:"a".repeat(64),goal_spec_hash:row.spec.intent_hash.clone(),observed_at:at,recorded_at:at,known:true,criteria:g.spec.criteria.iter().enumerate().map(|(i,c)|crate::pet_runtime::criteria::CriterionResult {criterion_index:i as u32,criterion_hash:model::fingerprint(c).unwrap(),status:crate::pet_runtime::criteria::Status::Met}).collect()};assert!(fake.valid());assert!(a.planning_feedback_report(&row.spec,proof,&fake).is_err());assert!(context(&a,&g,&o,"fake-round").is_err());assert_eq!(grant(&f,&g)["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),1);
}
#[test]fn uncertain_feedback_ack_recovers_the_same_evidence_and_missing_evidence_blocks_new_rounds() {
    let(f,mut a,g,_p,o,_)=setup_custom(true,18,4);let bus=Bus::new();let player=Player::new(&bus,"Private uncertain feedback");let(approved,ready)=reviewed(&o,&g,&bus);register(&a,&g,&o,&approved,&ready);assert_eq!(o.run_recipe_for_store(&native(&f),&g,&ready,||Ok(config()),|_|{}).unwrap().outcome,Outcome::CriteriaUnmet);let row=&g.admissions[0];let proof=row.proof.as_ref().unwrap();
    a.fault=AuthorityFault::BeforeGrantPublish;assert_eq!(a.record_planning_feedback(&row.spec,proof,o.lease(),ready.scope(),crate::assistant_memory::now()).err(),Some(Failure::Unavailable));a.fault=AuthorityFault::AfterGrantPublish;assert_eq!(a.record_planning_feedback(&row.spec,proof,o.lease(),ready.scope(),crate::assistant_memory::now()).err(),Some(Failure::Uncertain));a.fault=AuthorityFault::None;let f1=feedback(&a,&g,&o,&ready);assert_eq!(feedback(&a,&g,&o,&ready),f1);assert_eq!(player.calls.lock().unwrap().len(),2);
    let path=f.path.join("pet-runtime-step-consent-v1").join(format!("{}.verification.json",ready.scope().slot().unwrap()));std::fs::remove_file(path).unwrap();assert!(context(&a,&g,&o,"round-2").is_err());assert!(native(&f).read(&g.id,"ai_ollama").is_err());assert_eq!(grant(&f,&g)["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),3);
}
#[test]fn unchanged_verified_criterion_count_stops_replanning_before_original_call_caps_are_spent() {
    let(f,a,g,_p,o,_)=setup_policy(true,18,5,1);let bus=Bus::new();let _player=Player::new(&bus,"Private no progress feedback");let(approved,ready)=reviewed(&o,&g,&bus);register(&a,&g,&o,&approved,&ready);assert_eq!(o.run_recipe_for_store(&native(&f),&g,&ready,||Ok(config()),|_|{}).unwrap().outcome,Outcome::CriteriaUnmet);feedback(&a,&g,&o,&ready);
    propose(&a,&g,&o,"round-2",18);let g2=o.publish_generated_plan(&native(&f),"round-2",crate::assistant_memory::now()).unwrap().receipt.record;let(approved2,ready2)=last_review(&o,&g2,&bus,"repeat-unmet");register(&a,&g2,&o,&approved2,&ready2);assert_eq!(o.run_recipe_for_store(&native(&f),&g2,&ready2,||Ok(config()),|_|{}).unwrap().outcome,Outcome::CriteriaUnmet);feedback(&a,&g2,&o,&ready2);
    assert_eq!(context(&a,&g2,&o,"round-3").err(),Some(Failure::Capacity));let body=grant(&f,&g)["body"].clone();assert_eq!(body["planningUsage"]["rounds"].as_array().unwrap().len(),2);assert_eq!(body["budgetUsage"]["attempts"].as_array().unwrap().iter().filter(|c|c["kind"]=="model").count(),2);assert_eq!(g.admissions[0].spec.budget.max_model_calls,3);assert_eq!(g.admissions[0].spec.budget.max_tool_calls,5);
}
